template <typename T>
struct CustomLimits {
    static constexpr bool is_signed = true;
    static constexpr T minimum() { return T(0); }
    static constexpr const char* type_name = "Generic";
};

// Full Specialization for bool
template <>
struct CustomLimits<bool> {
    static constexpr bool is_signed = false;
    static constexpr bool minimum() { return false; }
    static constexpr const char* type_name = "Boolean";
};

// Usage
constexpr bool b_is_signed = CustomLimits<bool>::is_signed;
constexpr auto i_min = CustomLimits<int>::minimum();
